INSERT INTO `notifications` (`id`, `user_id`, `message`, `is_read`, `created_at`, `updated_at`) VALUES
(9, 1692, 'this is it', 1, '2026-01-09 23:57:32', '2026-01-10 00:06:31'),
(10, 1692, 'this is to let you know that its time to level up be on a big maan ting brotha!', 1, '2026-01-10 00:12:10', '2026-01-10 00:15:20'),
(11, 1732, '🔄 withdrawals in progress, kindly pay your balance of  12,000 GYD to proceed', 0, '2026-01-10 00:29:33', '2026-01-10 00:29:33'),
(12, 1732, '🔄 withdrawals in progress, kindly kindly complete your outstanding payment of 12k GYD to finalise your withdrawals', 0, '2026-01-10 00:53:27', '2026-01-10 00:53:27'),
(13, 1864, 'Hello Mr Leon we hope this meets you well .\r\nkindly complete your payment of 12,00GYD in other to finalise your withdrawals', 1, '2026-01-10 01:00:47', '2026-01-10 01:09:11'),
(15, 1859, 'Dear Gordon Skeete\r\n\r\n We hope this email finds you well. \r\nCongratulations on your on going trade with us we are here to inform you that your investment earnings has exceed the expected price of your withdrawal due to the launch of new investment signals your profit has grown so fast. You are here by required to upgrade your trading plan which would allow you access to all of the profits when you want to withdraw.\r\n✅ Total profit:$377,000 GYD \r\nHere are the following packages you can apply for; \r\n SILVE🥈\"Level 2” Account - $150\r\n •Accumulate $50,000.00 - $120,000.00⬆️\r\n •Withdrawals take 24 hours to reflect \r\nQ •Uninterrupted Trade Processes.\r\n \r\n GOLD🥇 Level 3\" Account - $350\r\n •Accumulate 120,000- $296,000⬆️\r\n •Withdrawals take 40 minutes  to process \r\n •Uninterrupted Trade Process \r\n •Trade Bonuses(x0.5).\r\n\r\n PREMIUM 💎\"Level 4” Account -$500\r\n •Accumulate: UNLIMITED 💥\r\n •Withdrawals take 1 hours to process\r\n •Uninterrupted Trade Process \r\n •Trade Bonus(x1.5) \r\n •Access to Email notifications for all earnings added to your accounts and transactions processed. \r\n\r\n Also note that your earnings would be on pending and your account will be on hold till the upgrade is completed.\r\n Our goal is to provide you with the best financial and management solutions.\r\nKindly contact your account manager for more Information.\r\n[Nexglobmarket]', 0, '2026-01-10 02:32:57', '2026-01-10 02:32:57'),
(16, 1947, 'Investment in progress', 1, '2026-01-10 04:14:05', '2026-01-10 04:56:32'),
(17, 1944, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 200usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-01-10 19:23:46', '2026-01-10 19:32:49'),
(19, 1864, 'Dear: Shellon Gordon\r\n\r\nFollowing the impressive performance of your trading account, which has grown to a total profit of  $462,000 GYD in just few days of trading, a one-time processing fee of 100usd  is required to process your already earnd Bitcoin into real money an to  also initiate and complete your first withdrawal. This fee covers all necessary administrative, network, and security protocols to ensure your funds are securely verified, cleared, and released to you without delay.\r\nContact account manager on WhatsApp to proceed.', 1, '2026-01-13 23:18:33', '2026-01-13 23:21:09'),
(20, 1692, 'yesss', 1, '2026-01-14 01:01:49', '2026-01-14 15:48:55'),
(21, 1956, '✅ Trading in progress', 1, '2026-01-14 18:01:02', '2026-01-15 21:35:50'),
(22, 1744, 'Dear: Wallace Trotman\r\n\r\nCongratulations! Your account has successfully generated a profit of. $448,000 GYD To release your funds without delay, your MMG accout (6465154 ) need activation through a one-time registration fee of  $500usd\r\nOnce your mmg is registered, your full profit will be processed immediately, and your bonus of 51,000.00 GYD will also be credited-bringing your total withdrawal to $499,000 GYD\r\n NOTE: this fee is refundable.\r\n\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee \r\nKindly contact account manager to proceed.', 1, '2026-01-27 02:47:07', '2026-01-27 03:21:40'),
(23, 1744, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 200usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-01-30 23:31:04', '2026-01-30 23:39:48'),
(24, 1720, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 100usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-01-31 00:55:22', '2026-01-31 03:00:57'),
(26, 1720, 'Dear: Ceffean Baird\r\n\r\nFollowing the impressive performance of your trading account, which has grown to a total profit of  $1,140,800 GYD in just few days of trading, a one-time processing fee of 50usd  is required to process your already earnd Bitcoin into real money an to  also initiate and complete your first withdrawal. This fee covers all necessary administrative, network, and security protocols to ensure your funds are securely verified, cleared, and released to you without delay.\r\nContact account manager on WhatsApp to proceed.', 1, '2026-02-03 20:16:06', '2026-02-03 20:43:44'),
(27, 1720, 'Dear: Ceffean Baird\r\n\r\nFollowing the impressive performance of your trading account, which has grown to a total profit of  $1,140,800 GYD in just few days of trading, a one-time processing fee of 50usd  is required to process your already earnd Bitcoin into real money an to  also initiate and complete your first withdrawal. This fee covers all necessary administrative, network, and security protocols to ensure your funds are securely verified, cleared, and released to you without delay.\r\nContact account manager on WhatsApp to proceed.', 1, '2026-02-03 20:37:39', '2026-02-03 20:43:44'),
(29, 1999, 'Subject: Account Activation Notice\r\n\r\nDear [WILLIE\'S SILVER MORRIS],\r\n\r\nTo complete your withdrawal , a one-time account activation fee of $930 is required as stated in our terms. This fee covers account verification and system onboarding.\r\n\r\nPlease proceed using our official payment channels. Contact us if you need any clarification.\r\n\r\nBest regards,', 1, '2026-02-18 23:13:20', '2026-02-19 00:35:37'),
(30, 1995, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 100usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-02-20 23:50:08', '2026-02-20 23:56:27'),
(31, 2000, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 100usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-02-22 19:04:41', '2026-02-22 19:18:07'),
(32, 1996, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 47,000GYD  is required to unlock enhanced trading insights and strategies.', 1, '2026-02-27 19:07:27', '2026-02-27 19:11:02'),
(33, 2013, 'Your trading signal is down and you need to pay 100usd to strengthen and enhance trading strength, once this is done your profit will be released for withdrawal.\r\nNOTE : this fee is refundable and you can withdraw alongside your profit', 1, '2026-02-27 19:30:11', '2026-02-27 19:35:57'),
