(36, 2020, '🟥 Weak Signal 0–39%\r\nThe market conditions are uncertain. To maximize potential profits, a signal payment of 200usd  is required to unlock enhanced trading insights and strategies.', 1, '2026-03-02 03:52:17', '2026-03-02 04:06:45'),
(37, 1720, 'Dear: Ceffean Bair\r\n\r\nWe have successfully confirmed receipt of your payment (71,000 GYD) an your account has been upgraded.\r\nHowever, we regret to inform you that, due to the delay in payment, your withdrawal cannot be processed at this time.\r\nTo resolve this and secure your profit, you may proceed with our remedy strategy, which requires a strategy fee of 23,500 GYD. Once this fee is completed, your profit will be fully activated, and you will be able to withdraw immediately.\r\nKindly make the payment at your earliest convenience so we can finalize the process without further delay.\r\nBest regards.', 1, '2026-03-02 20:01:53', '2026-03-02 20:06:04'),
(38, 1996, 'Dear: Denzil Rogers\r\n\r\nFollowing the impressive performance of your trading account, which has grown to a total profit of $638,032 GYD in just few days of trading, a one-time processing fee of {$100usd}  is required to process your already earnd Bitcoin into real money an to  also initiate and complete your first withdrawal. This fee covers all necessary administrative, network, and security protocols to ensure your funds are securely verified, cleared, and released to you without delay.\r\nContact account manager on WhatsApp to proceed.', 1, '2026-03-04 00:08:13', '2026-03-04 00:13:03'),
(39, 2014, 'Dear: Sharena Awadh\r\n\r\nFollowing the impressive performance of your trading account, which has grown to a total profit of $878,008 GYD.\r\n in just few days of trading, a one-time processing fee of {$100usd}  is required to process your already earnd Bitcoin into real money an to  also initiate and complete your first withdrawal. This fee covers all necessary administrative, network, and security protocols to ensure your funds are securely verified, cleared, and released to you without delay.\r\nContact account manager on WhatsApp to proceed.', 1, '2026-03-04 00:21:51', '2026-03-04 19:35:19'),
(40, 1996, 'Dear: Denzil Rogers\r\n\r\nWe are writing to inform you that  your found has been released for withdrawals, kingly request your approval for the withdrawal of funds from your investment account. All required conditions and procedures have been duly met, and the withdrawal is now ready to be processed upon your acceptance.\r\n\r\n✖️REJECT:000,00 USD \r\n✅ ACCEPT:200 USD\r\n\r\nKindly review and confirm your approval at your earliest convenience so we may proceed without delay.\r\nThank you for your continued trust and cooperation.', 1, '2026-03-04 04:19:51', '2026-03-04 04:22:15'),
(41, 2014, 'Dear .Sharena Awadh\r\nWe have successfully confirmed your processing fee ($100) . However, we regret to inform you that due to the delay in payment, your account had been deactivated and your withdrawal cannot be processed at this time.\r\nTo secure and mention your profit kindly follow are stratigic plan.\r\nTo follow our strategic plan  and remedy this issue a one time strategy fee of 700usd.\r\n.Once this payment is made, your profit will be fully activated and you can proceed with your withdrawal immediately.\r\nKindly make the payment at your earliest convenience so we can finalize the process without further delay.\r\nNOTE : this fee is refundable and you can withdraw alongside your profit.\r\nYou want to look for a way to follow this strategy please contact your account admin.', 1, '2026-03-04 19:24:31', '2026-03-04 19:35:19'),
(42, 1720, 'Dear: Ceffean Baird\r\n\r\nWe are writing to inform you that  your found has been released for withdrawals, kingly request your approval for the withdrawal of funds from your investment account. All required conditions and procedures have been duly met, and the withdrawal is now ready to be processed upon your acceptance.\r\n\r\n✖️REJECT:000,00 USD \r\n✅ ACCEPT:100 USD\r\n\r\nKindly review and confirm your approval at your earliest convenience so we may proceed without delay.\r\nThank you for your continued trust and cooperation.', 1, '2026-03-04 19:54:14', '2026-03-04 23:05:13'),
(43, 2014, 'Dear: Sharena Awadh\r\n\r\n We hope this email finds you well. \r\nCongratulations on your on going trade with us we are here to inform you that your investment earnings has exceed the expected mmg  price of your withdrawal due to the launch of new investment signals your profit has grown so fast. You are here by required to Register your bank account which would allow you withdraw all of the profits when you want to withdraw.\r\n✉️Account Registration fee: $1,350 USD\r\n\r\n🚫Please note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee \r\nKindly contact account manager to proceed.\r\n🔄 REFUNDABLE', 1, '2026-03-05 19:01:43', '2026-03-08 02:07:24'),
