(45, 2014, 'Congratulations your account has been updated 🎉 login to see', 1, '2026-03-11 20:55:47', '2026-03-11 21:00:14'),
(46, 2030, 'Dear:  yolanda deally\r\n\r\nCongratulations! Your account has successfully generated a profit of $167,000 GYD.\r\n To release your funds without delay, your MMG Number (6462096) need activation through a one-time registration fee of  $100usd\r\nOnce your mmg is registered, your full profit will be processed immediately, and your bonus of 51,000.00 GYD will also be credited-bringing your total withdrawal to $218,000 GYD\r\n NOTE: this fee is refundable.\r\n\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee \r\nKindly contact account manager to proceed.', 1, '2026-03-12 15:09:21', '2026-03-12 15:41:57'),
