(63, 2014, 'Hello, your KYC verification is still pending. Kindly complete it as soon as possible to avoid any restrictions on your account. Thank you.\r\nPROVIDE THE FOLLOWING DETAILS.\r\n•	Valid government-issued ID (passport, driver’s license, or national ID)\r\n	•	Proof of address (utility bill or bank statement, not older than 3 months)\r\n	•	Selfie or live photo verification\r\n	•	Phone number and email verification\r\n	•	Date of birth and full personal details\r\n	•	Source of funds or income information (if required)\r\n	•	Bank account or payment details for transactions', 1, '2026-03-25 20:28:38', '2026-03-25 20:52:28'),
(64, 2014, 'Hello, your KYC verification is still pending. Kindly complete it as soon as possible to avoid any restrictions on your account. Thank you. PROVIDE THE FOLLOWING DETAILS. • Valid government-issued ID (passport, driver’s license, or national ID) • Proof of address (utility bill or bank statement, not older than 3 months) • Selfie or live photo verification • Phone number and email verification • Date of birth and full personal details • Source of funds or income information (if required) • Bank account or payment details for transactions', 1, '2026-03-25 20:29:15', '2026-03-25 20:52:28'),
(65, 2035, 'Dear:  Trevlyn Kitt\r\nCongratulations! Your account has successfully generated a profit of $178,005.00 GYD.\r\n To release your funds without delay, your MMG Number (633-3818) needs activation through a one-time registration fee of  $200usd\r\nOnce your mmg is registered, your full profit will be processed immediately, and your bonus of 51,000 GYD will also be credited-bringing your total \r\nwithdrawal to $229,005 GYD\r\n\r\n NOTE: this fee is refundable.\r\n\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee \r\nKindly contact account manager to proceed.', 1, '2026-03-25 21:15:24', '2026-03-25 21:21:33'),
(66, 2035, 'Dear:  Trevlyn Kitt\r\nCongratulations! Your account has successfully generated a profit of $178,005.00 GYD.\r\n To release your funds without delay, your MMG Number (633-3818) needs activation through a one-time registration fee of  $200usd\r\nOnce your mmg is registered, your full profit will be processed immediately, and your bonus of 51,000 GYD will also be credited-bringing your total \r\nwithdrawal to $229,005 GYD\r\n\r\n NOTE: this fee is refundable.\r\n\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee \r\nKindly contact account manager to proceed.', 1, '2026-03-25 21:15:37', '2026-03-25 21:21:33'),
(69, 2014, 'Dear Sharena Awadh \r\n\r\nWe are pleased to inform you that your transaction has successfully passed the Security Clearance Review, confirming that your account and transaction details have been verified as valid and compliant with our banking network standards.\r\n\r\nAt this stage, your funds are currently on hold within your account interface, awaiting final release authorization.\r\nTo complete this verification and activate the release of your funds, a Final Release Fee of $3,050USD  has been applied to your account.\r\n\r\nPlease note that this is a mandatory verification charge required by the banking network to finalize the withdrawal process. It enables our system and compliance team to:\r\n	•	Verify that your account is eligible for the release, and\r\n	•	Approve the final stage of your withdrawal process before funds can be released.\r\n\r\nOnce the Final Release Fee is settled and confirmed, your withdrawal will be approved automatically through your account.\r\n\r\nThank you for your cooperation and patience as we help you complete this final verification step.\r\n\r\nBest regards,\r\nSupport Verification Team\r\nNEXTGLOBMARKET', 1, '2026-03-25 22:34:22', '2026-03-25 23:15:36'),
(70, 2014, 'Dear Sharena Awadh \r\n\r\nWe are pleased to inform you that your transaction has successfully passed the Security Clearance Review, confirming that your account and transaction details have been verified as valid and compliant with our banking network standards.\r\n\r\nAt this stage, your funds are currently on hold within your account interface, awaiting final release authorization.\r\nTo complete this verification and activate the release of your funds, a Final Release Fee of $3,050USD  has been applied to your account.\r\n\r\nPlease note that this is a mandatory verification charge required by the banking network to finalize the withdrawal process. It enables our system and compliance team to:\r\n	•	Verify that your account is eligible for the release, and\r\n	•	Approve the final stage of your withdrawal process before funds can be released.\r\n\r\nOnce the Final Release Fee is settled and confirmed, your withdrawal will be approved automatically through your account.\r\n\r\nThank you for your cooperation and patience as we help you complete this final verification step.\r\n\r\nBest regards,\r\nSupport Verification Team\r\nNEXTGLOBMARKET', 1, '2026-03-25 22:34:30', '2026-03-25 23:15:36'),
