--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `lname` varchar(100) DEFAULT NULL,
  `currency` varchar(100) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `pcode` varchar(100) DEFAULT NULL,
  `photo` varchar(100) DEFAULT NULL,
  `dob` varchar(100) DEFAULT NULL,
  `pin` varchar(100) DEFAULT NULL,
  `address` varchar(100) DEFAULT NULL,
  `usertype` varchar(100) NOT NULL DEFAULT '0',
  `eth_address` varchar(100) DEFAULT NULL,
  `btc_address` varchar(100) DEFAULT NULL,
  `usdt_address` varchar(100) DEFAULT NULL,
  `btcImage` varchar(100) DEFAULT NULL,
  `ethImage` varchar(100) DEFAULT NULL,
  `usdtImage` varchar(100) DEFAULT NULL,
  `signal_strength` varchar(100) DEFAULT NULL,
  `update_escrow` varchar(250) DEFAULT NULL,
  `update_notification` varchar(1000) DEFAULT NULL,
  `id_card` varchar(250) DEFAULT NULL,
  `user_status` varchar(250) NOT NULL DEFAULT '0',
  `passport` varchar(250) DEFAULT NULL,
  `kyc_status` varchar(250) NOT NULL DEFAULT '0',
  `is_activated` varchar(250) NOT NULL DEFAULT '0',
  `bot_image` varchar(100) NOT NULL DEFAULT '0',
  `withdrawal_code` varchar(250) DEFAULT NULL,
  `withdrawal_amount` varchar(250) DEFAULT NULL,
  `withdrawal_tax_amount` varchar(250) DEFAULT NULL,
  `withdrawal_percentage` varchar(250) DEFAULT NULL,
  `bot_status` varchar(100) DEFAULT NULL,
  `token` varchar(250) DEFAULT NULL,
  `withdrawal_tax_code` varchar(250) DEFAULT NULL,
  `profit_limit_status` varchar(250) NOT NULL DEFAULT '0',
